  "sv.mfa_on_ok": { pt: "Pronto! A partir de agora, ao entrar, pedimos também o código da APP autenticadora.", en: "Done! From now on, when you sign in, we'll also ask for the code from your authenticator app.", zh: "完成！从现在起，登录时我们还会要求输入身份验证器应用中的验证码。" },
  "sv.mfa_no_app": { pt: "Não encontrámos uma APP autenticadora neste telemóvel. Instale uma (por exemplo Google Authenticator) ou escreva a chave à mão.", en: "We couldn't find an authenticator app on this phone. Install one (for example Google Authenticator) or type the key by hand.", zh: "在这部手机上未找到身份验证器应用。请安装一个（例如 Google Authenticator），或手动输入密钥。" },
  "sv.mfa_off_ok": { pt: "A entrada em dois passos foi desligada. Agora basta a palavra-passe para entrar.", en: "Two-step sign-in has been turned off. Now your password alone is enough to sign in.", zh: "两步登录已关闭。现在只需密码即可登录。" },
  "sv.mfa_off_q": { pt: "Desligar a entrada em dois passos?", en: "Turn off two-step sign-in?", zh: "关闭两步登录？" },
  "sv.mfa_off_warn": { pt: "A sua conta fica menos protegida: quem souber a palavra-passe consegue entrar.", en: "Your account will be less protected: anyone who knows the password can sign in.", zh: "您的账户安全性会降低：知道密码的人就能登录。" },
  "sv.turn_off": { pt: "Desligar", en: "Turn off", zh: "关闭" },
  "sv.turn_on": { pt: "Ligar", en: "Turn on", zh: "开启" },
  "sv.mfa_title": { pt: "🔐 Entrar em dois passos", en: "🔐 Two-step sign-in", zh: "🔐 两步登录" },
  "sv.mfa_intro": { pt: "Além da palavra-passe, ao entrar pedimos um código de 6 algarismos que muda a cada 30 segundos numa APP autenticadora. Assim, mesmo que alguém descubra a sua palavra-passe, não consegue entrar.", en: "Besides your password, when you sign in we ask for a 6-digit code that changes every 30 seconds in an authenticator app. That way, even if someone finds out your password, they can't sign in.", zh: "除密码外，登录时我们还会要求输入身份验证器应用中每 30 秒变化一次的 6 位验证码。这样，即使有人知道了您的密码，也无法登录。" },
  "sv.mfa_need_code": { pt: "Esta conta já tem a entrada em dois passos ligada. Para mudar, escreva primeiro o código que a APP autenticadora mostra agora.", en: "This account already has two-step sign-in turned on. To change it, first enter the code your authenticator app shows now.", zh: "此账户已开启两步登录。如需更改，请先输入身份验证器应用当前显示的验证码。" },
  "sv.mfa_on": { pt: "✔ Ligada", en: "✔ On", zh: "✔ 已开启" },
  "sv.mfa_on_text": { pt: "Ao entrar, depois da palavra-passe, pedimos o código da APP autenticadora.", en: "When you sign in, after your password, we ask for the code from your authenticator app.", zh: "登录时，在输入密码后，我们会要求输入身份验证器应用中的验证码。" },
  "sv.mfa_since": { pt: "Ligada desde {date}", en: "On since {date}", zh: "自 {date} 起开启" },
  "sv.mfa_phone_warn": { pt: "⚠️ Se mudar de telemóvel, ligue a APP autenticadora no novo telemóvel antes de apagar a do antigo.", en: "⚠️ If you change phones, set up the authenticator app on the new phone before deleting it from the old one.", zh: "⚠️ 如果更换手机，请先在新手机上设置身份验证器应用，再删除旧手机上的。" },
  "sv.wait": { pt: "Aguarde…", en: "Please wait…", zh: "请稍候…" },
