  "sv.mfa_this_phone_text": { pt: "Se a APP autenticadora está neste telemóvel, carregue no botão. Se não abrir, escreva a chave à mão na APP.", en: "If the authenticator app is on this phone, tap the button. If it doesn't open, type the key into the app by hand.", zh: "如果身份验证器应用在这部手机上，请点击按钮。如果无法打开，请在应用中手动输入密钥。" },
